Method.Source:
/// <summary>
///  M.essl 11.03.2024
/// </summary>
/// <returns>int</returns>
public int active()
{
    int ret = next active();

    InventLocation InventLocation = this.cursor();

    FormCheckBoxControl AVAAutoPackingSlipProcess = this.formRun().design().controlName(formControlStr(InventLocation, AVAAutoPackingSlipProcess));
    FormCheckBoxControl AVAAutoBillofLoadingProcess = this.formRun().design().controlName(formControlStr(InventLocation, AVAAutoBillofLoadingProcess));

    if (InventLocation.AVAAutoShippingProcess)
    {
        AVAAutoPackingSlipProcess.enabled(true);
        AVAAutoBillofLoadingProcess.enabled(true);
    }
    else
    {
        AVAAutoPackingSlipProcess.enabled(false);
        AVAAutoBillofLoadingProcess.enabled(false);
    } 


    return ret;
}
